def is_mac(s):
    parts = s.split(':')
    if len(parts) != 6:
        return False
    for p in parts:
        if len(p) != 2 or any(c not in '0123456789abcdefABCDEF' for c in p):
            return False
    return True

def is_ipv4(s):
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for x in parts:
        if not x.isdigit() or int(x) > 255:
            return False
    return True

def compress6(a):
    g = [format(int(x, 16), 'x') for x in a.split(':')]
    best, bl, i = -1, 0, 0
    while i < 8:
        if g[i] == '0':
            j = i
            while j < 8 and g[j] == '0':
                j += 1
            if j - i > bl:
                best, bl = i, j - i
            i = j
        else:
            i += 1
    if bl < 2:
        return ':'.join(g)
    return ':'.join(g[:best]) + '::' + ':'.join(g[best+bl:])

def parse_url(u):
    proto, rest = u.split('://', 1)
    if '/' in rest:
        hostport, path = rest.split('/', 1)
        path = '/' + path
    else:
        hostport, path = rest, '/'
    if path == '/':
        path = '/index.html'
    if ':' in hostport:
        host, port = hostport.split(':')
        port = int(port)
    else:
        host = hostport
        port = {'http': 80, 'https': 443, 'ftp': 21}[proto]
    return (proto, host, port, path)

